79:     for (int i = 0; i < count; ++i) {
80:         float S = Sa[i], X = Xa[i];
81:         float T = Ta[i], r = ra[i];
82:         float v = va[i];
83: 
84:         float dt = T / BINOMIAL_NUM;
85:         float u = expf(v * sqrtf(dt));
86:         float d = 1.f / u;
87:         float disc = expf(r * dt);
88:         float Pu = (disc - d) / (u - d);
89: 
90:         for (int j = 0; j < BINOMIAL_NUM; ++j) {
91:             float upow = powf(u, (float)(2 * j - BINOMIAL_NUM));
92:             V[j] = std::max(0.f, X - S * upow);
93:         }
