137: 
138:         float dt = T / BINOMIAL_NUM;
139:         float u = expf(v * sqrtf(dt));
140:         float d = 1.f / u;
141:         float disc = expf(r * dt);
142:         float Pu = (disc - d) / (u - d);
143: 
144:         for (int j = 0; j < BINOMIAL_NUM; ++j) {
145:             float upow = powf(u, (float)(2 * j - BINOMIAL_NUM));
146:             V[j] = std::max(0.f, X - S * upow);
147:         }
148: 
149:         for (int j = BINOMIAL_NUM - 1; j >= 0; --j)
150:             for (int k = 0; k < j; ++k)
151:                 V[k] = ((1 - Pu) * V[k] + Pu * V[k + 1]) / disc;
152: 
153:         result[i] = V[0];
154:     }
