57: // Vectorize the supplied CND polynomial while retaining its scalar expf calls.
58: static inline __m256 CND8(__m256 X) {
59:     const __m256 one = _mm256_set1_ps(1.f);
60:     const __m256 abs_mask = _mm256_castsi256_ps(_mm256_set1_epi32(0x7fffffff));
61:     const __m256 L = _mm256_and_ps(X, abs_mask);
62: 
63:     const __m256 k = _mm256_div_ps(
64:         one, _mm256_add_ps(one, _mm256_mul_ps(_mm256_set1_ps(0.2316419f), L)));
65:     const __m256 k2 = _mm256_mul_ps(k, k);
66:     const __m256 k3 = _mm256_mul_ps(k2, k);
67:     const __m256 k4 = _mm256_mul_ps(k2, k2);
68:     const __m256 k5 = _mm256_mul_ps(k3, k2);
69: 
70:     __m256 w = _mm256_mul_ps(_mm256_set1_ps(0.31938153f), k);
71:     w = _mm256_sub_ps(w, _mm256_mul_ps(_mm256_set1_ps(0.356563782f), k2));
72:     w = _mm256_add_ps(w, _mm256_mul_ps(_mm256_set1_ps(1.781477937f), k3));
73:     w = _mm256_add_ps(w, _mm256_mul_ps(_mm256_set1_ps(-1.821255978f), k4));
74:     w = _mm256_add_ps(w, _mm256_mul_ps(_mm256_set1_ps(1.330274429f), k5));
75: 
76:     float abs_values[8];
77:     float exp_values[8];
78:     _mm256_storeu_ps(abs_values, L);
79:     for (int lane = 0; lane < 8; ++lane)
80:         exp_values[lane] = expf(-abs_values[lane] * abs_values[lane] * .5f);
81:     const __m256 exp_values_v = _mm256_loadu_ps(exp_values);
82:     w = _mm256_mul_ps(
83:         w, _mm256_mul_ps(_mm256_set1_ps(0.39894228040f), exp_values_v));
84: 
85:     const __m256 positive = _mm256_cmp_ps(X, _mm256_setzero_ps(), _CMP_GT_OQ);
86:     return _mm256_blendv_ps(w, _mm256_sub_ps(one, w), positive);
87: }
