97:         const __m256 r = _mm256_loadu_ps(ra + i);
98:         const __m256 v = _mm256_loadu_ps(va + i);
99: 
100:         float ratio_values[8];
101:         float log_values[8];
102:         _mm256_storeu_ps(ratio_values, _mm256_div_ps(S, X));
103:         for (int lane = 0; lane < 8; ++lane)
104:             log_values[lane] = logf(ratio_values[lane]);
105: 
106:         const __m256 v_squared = _mm256_mul_ps(v, v);
107:         const __m256 half_v_squared = _mm256_mul_ps(v_squared, _mm256_set1_ps(.5f));
108:         const __m256 rate_plus_half_v_squared = _mm256_add_ps(r, half_v_squared);
109:         const __m256 numerator = _mm256_add_ps(
110:             _mm256_loadu_ps(log_values), _mm256_mul_ps(rate_plus_half_v_squared, T));
111:         const __m256 sqrt_T = _mm256_sqrt_ps(T);
112:         const __m256 v_sqrt_T = _mm256_mul_ps(v, sqrt_T);
113:         const __m256 d1 = _mm256_div_ps(numerator, v_sqrt_T);
114:         const __m256 d2 = _mm256_sub_ps(d1, v_sqrt_T);
115: 
116:         const __m256 cnd_d1 = CND8(d1);
117:         const __m256 cnd_d2 = CND8(d2);
118:         float discount_values[8];
119:         for (int lane = 0; lane < 8; ++lane)
120:             discount_values[lane] = expf(-ra[i + lane] * Ta[i + lane]);
121:         const __m256 discount = _mm256_loadu_ps(discount_values);
122: 
123:         const __m256 first_term = _mm256_mul_ps(S, cnd_d1);
124:         const __m256 second_term = _mm256_mul_ps(
125:             _mm256_mul_ps(X, discount), cnd_d2);
126:         _mm256_storeu_ps(result + i, _mm256_sub_ps(first_term, second_term));
127:     }
