134: 
135:         float d1 = (logf(S / X) + (r + v * v * .5f) * T) / (v * sqrtf(T));
136:         float d2 = d1 - v * sqrtf(T);
137: 
138:         result[i] = S * CND(d1) - X * expf(-r * T) * CND(d2);
139:     }
