157: void binomial_put_serial(float Sa[], float Xa[], float Ta[], float ra[], float va[], float result[], int count) {
158:     float V[BINOMIAL_NUM];
159: 
160:     for (int i = 0; i < count; ++i) {
161:         float S = Sa[i], X = Xa[i];
162:         float T = Ta[i], r = ra[i];
163:         float v = va[i];
164: 
165:         float dt = T / BINOMIAL_NUM;
166:         float u = expf(v * sqrtf(dt));
167:         float d = 1.f / u;
168:         float disc = expf(r * dt);
169:         float Pu = (disc - d) / (u - d);
170: 
171:         for (int j = 0; j < BINOMIAL_NUM; ++j) {
172:             float upow = powf(u, (float)(2 * j - BINOMIAL_NUM));
173:             V[j] = std::max(0.f, X - S * upow);
174:         }
175: 
176:         for (int j = BINOMIAL_NUM - 1; j >= 0; --j)
177:             for (int k = 0; k < j; ++k)
178:                 V[k] = ((1 - Pu) * V[k] + Pu * V[k + 1]) / disc;
179: 
180:         result[i] = V[0];
181:     }
182: }
