38: // Cumulative normal distribution function. Keep the supplied approximation.
39: static inline float CND(float X) {
40:     float L = fabsf(X);
41: 
42:     float k = 1.f / (1.f + 0.2316419f * L);
43:     float k2 = k * k;
44:     float k3 = k2 * k;
45:     float k4 = k2 * k2;
46:     float k5 = k3 * k2;
47: 
48:     const float invSqrt2Pi = 0.39894228040f;
49:     float w = (0.31938153f * k - 0.356563782f * k2 + 1.781477937f * k3 + -1.821255978f * k4 + 1.330274429f * k5);
50:     w *= invSqrt2Pi * expf(-L * L * .5f);
51: 
52:     if (X > 0.f)
53:         w = 1.f - w;
54:     return w;
55: }
