58: // Vector log for normal positive ratios. The atanh series is evaluated on a
59: // mantissa reduced to [sqrt(1/2), sqrt(2)]; exceptional lanes use logf.
60: static inline __m256 bs_log_ratio_avx2(__m256 numerator, __m256 denominator) {
61:     const __m256 ratio = _mm256_div_ps(numerator, denominator);
62:     const __m256i bits = _mm256_castps_si256(ratio);
63:     const __m256i raw_exponent = _mm256_and_si256(
64:         _mm256_srli_epi32(bits, 23), _mm256_set1_epi32(0xff));
65:     __m256i exponent = _mm256_sub_epi32(raw_exponent, _mm256_set1_epi32(127));
66: 
67:     const __m256i mantissa_bits = _mm256_or_si256(
68:         _mm256_and_si256(bits, _mm256_set1_epi32(0x007fffff)),
69:         _mm256_set1_epi32(0x3f800000));
70:     const __m256 mantissa = _mm256_castsi256_ps(mantissa_bits);
71:     const __m256 reduce = _mm256_cmp_ps(
72:         mantissa, _mm256_set1_ps(1.41421356237f), _CMP_GT_OQ);
73:     const __m256 adjusted_mantissa = _mm256_blendv_ps(
74:         mantissa, _mm256_mul_ps(mantissa, _mm256_set1_ps(0.5f)), reduce);
75:     const __m256i exponent_adjustment = _mm256_and_si256(
76:         _mm256_castps_si256(reduce), _mm256_set1_epi32(1));
77:     exponent = _mm256_add_epi32(exponent, exponent_adjustment);
78: 
79:     const __m256 one = _mm256_set1_ps(1.0f);
80:     const __m256 z = _mm256_div_ps(
81:         _mm256_sub_ps(adjusted_mantissa, one),
82:         _mm256_add_ps(adjusted_mantissa, one));
83:     const __m256 z2 = _mm256_mul_ps(z, z);
84:     __m256 polynomial = _mm256_set1_ps(1.0f / 15.0f);
85:     polynomial = _mm256_add_ps(_mm256_set1_ps(1.0f / 13.0f), _mm256_mul_ps(z2, polynomial));
86:     polynomial = _mm256_add_ps(_mm256_set1_ps(1.0f / 11.0f), _mm256_mul_ps(z2, polynomial));
87:     polynomial = _mm256_add_ps(_mm256_set1_ps(1.0f / 9.0f), _mm256_mul_ps(z2, polynomial));
88:     polynomial = _mm256_add_ps(_mm256_set1_ps(1.0f / 7.0f), _mm256_mul_ps(z2, polynomial));
89:     polynomial = _mm256_add_ps(_mm256_set1_ps(1.0f / 5.0f), _mm256_mul_ps(z2, polynomial));
90:     polynomial = _mm256_add_ps(_mm256_set1_ps(1.0f / 3.0f), _mm256_mul_ps(z2, polynomial));
91:     polynomial = _mm256_add_ps(one, _mm256_mul_ps(z2, polynomial));
92: 
93:     const __m256 log_mantissa = _mm256_mul_ps(
94:         _mm256_mul_ps(_mm256_set1_ps(2.0f), z), polynomial);
95:     const __m256 log_approximation = _mm256_add_ps(
96:         _mm256_mul_ps(_mm256_cvtepi32_ps(exponent),
97:                       _mm256_set1_ps(0.6931471805599453f)),
98:         log_mantissa);
99: 
100:     float ratios[8];
101:     float logarithms[8];
102:     _mm256_storeu_ps(ratios, ratio);
103:     _mm256_storeu_ps(logarithms, log_approximation);
104:     for (int lane = 0; lane < 8; ++lane) {
105:         std::uint32_t raw;
106:         std::memcpy(&raw, &ratios[lane], sizeof(raw));
107:         const unsigned int raw_exp = (raw >> 23) & 0xffu;
108:         if (raw_exp == 0u || raw_exp == 0xffu || (raw & 0x80000000u) != 0u)
109:             logarithms[lane] = logf(ratios[lane]);
110:     }
111:     return _mm256_loadu_ps(logarithms);
112: }
