161: void binomial_put_serial(float Sa[], float Xa[], float Ta[], float ra[], float va[], float result[], int count) {
162:     float V[BINOMIAL_NUM];
163: 
164:     for (int i = 0; i < count; ++i) {
165:         float S = Sa[i], X = Xa[i];
166:         float T = Ta[i], r = ra[i];
167:         float v = va[i];
168: 
169:         float dt = T / BINOMIAL_NUM;
170:         float u = expf(v * sqrtf(dt));
171:         float d = 1.f / u;
172:         float disc = expf(r * dt);
173:         float Pu = (disc - d) / (u - d);
174: 
175:         for (int j = 0; j < BINOMIAL_NUM; ++j) {
176:             float upow = powf(u, (float)(2 * j - BINOMIAL_NUM));
177:             V[j] = std::max(0.f, X - S * upow);
178:         }
179: 
180:         for (int j = BINOMIAL_NUM - 1; j >= 0; --j)
181:             for (int k = 0; k < j; ++k)
182:                 V[k] = ((1 - Pu) * V[k] + Pu * V[k + 1]) / disc;
183: 
184:         result[i] = V[0];
185:     }
186: }
