115: void black_scholes_serial(float Sa[], float Xa[], float Ta[], float ra[], float va[], float result[], int count) {
116:     int i = 0;
117: #if defined(__AVX2__)
118:     const __m256 half = _mm256_set1_ps(0.5f);
119:     for (; count - i >= 8; i += 8) {
120:         const __m256 S = _mm256_loadu_ps(Sa + i);
121:         const __m256 X = _mm256_loadu_ps(Xa + i);
122:         const __m256 T = _mm256_loadu_ps(Ta + i);
123:         const __m256 r = _mm256_loadu_ps(ra + i);
124:         const __m256 v = _mm256_loadu_ps(va + i);
125: 
126:         const __m256 log_ratio = bs_log_ratio_avx2(S, X);
127:         const __m256 sqrt_T = _mm256_sqrt_ps(T);
128:         const __m256 v_sqrt_T = _mm256_mul_ps(v, sqrt_T);
129:         const __m256 v_squared_half = _mm256_mul_ps(
130:             _mm256_mul_ps(v, v), half);
131:         const __m256 rate_term = _mm256_mul_ps(
132:             _mm256_add_ps(r, v_squared_half), T);
133:         const __m256 numerator = _mm256_add_ps(log_ratio, rate_term);
134:         const __m256 d1 = _mm256_div_ps(numerator, v_sqrt_T);
135:         const __m256 d2 = _mm256_sub_ps(d1, v_sqrt_T);
136: 
137:         float d1_lanes[8];
138:         float d2_lanes[8];
139:         _mm256_storeu_ps(d1_lanes, d1);
140:         _mm256_storeu_ps(d2_lanes, d2);
141:         for (int lane = 0; lane < 8; ++lane) {
142:             const int index = i + lane;
143:             result[index] = Sa[index] * CND(d1_lanes[lane]) -
144:                             Xa[index] * expf(-ra[index] * Ta[index]) *
145:                             CND(d2_lanes[lane]);
146:         }
147:     }
148: #endif
149:     for (; i < count; ++i) {
150:         float S = Sa[i], X = Xa[i];
151:         float T = Ta[i], r = ra[i];
152:         float v = va[i];
153: 
154:         float d1 = (logf(S / X) + (r + v * v * .5f) * T) / (v * sqrtf(T));
155:         float d2 = d1 - v * sqrtf(T);
156: 
157:         result[i] = S * CND(d1) - X * expf(-r * T) * CND(d2);
158:     }
159: }
