33: // Cumulative normal distribution function
34: static inline float CND(float X) {
35:     float L = fabsf(X);
36: 
37:     float k = 1.f / (1.f + 0.2316419f * L);
38: 
39:     const float invSqrt2Pi = 0.39894228040f;
40:     float w = ((((1.330274429f * k - 1.821255978f) * k + 1.781477937f) * k - 0.356563782f) * k + 0.31938153f) * k;
41:     w *= invSqrt2Pi * expf(-L * L * .5f);
42: 
43:     if (X > 0.f)
44:         w = 1.f - w;
45:     return w;
46: }
