48: static inline float black_scholes_value(float S, float X, float T, float r, float v) {
49:     float d1 = (logf(S / X) + (r + v * v * .5f) * T) / (v * sqrtf(T));
50:     float d2 = d1 - v * sqrtf(T);
51:     return S * CND(d1) - X * expf(-r * T) * CND(d2);
52: }
