54: #if defined(__AVX2__)
55: // Keep the polynomial Horner steps in AVX2; expf remains lane-wise.
56: static inline __m256 CND8(__m256 X) {
57:     const __m256 one = _mm256_set1_ps(1.f);
58:     const __m256 abs_mask = _mm256_castsi256_ps(_mm256_set1_epi32(0x7fffffff));
59:     const __m256 L = _mm256_and_ps(X, abs_mask);
60:     const __m256 k = _mm256_div_ps(
61:         one,
62:         _mm256_add_ps(one, _mm256_mul_ps(_mm256_set1_ps(0.2316419f), L)));
63: 
64:     __m256 w = _mm256_mul_ps(_mm256_set1_ps(1.330274429f), k);
65:     w = _mm256_sub_ps(w, _mm256_set1_ps(1.821255978f));
66:     w = _mm256_add_ps(_mm256_mul_ps(w, k), _mm256_set1_ps(1.781477937f));
67:     w = _mm256_sub_ps(_mm256_mul_ps(w, k), _mm256_set1_ps(0.356563782f));
68:     w = _mm256_add_ps(_mm256_mul_ps(w, k), _mm256_set1_ps(0.31938153f));
69:     w = _mm256_mul_ps(w, k);
70: 
71:     float abs_lanes[8];
72:     float factor_lanes[8];
73:     _mm256_storeu_ps(abs_lanes, L);
74:     const float invSqrt2Pi = 0.39894228040f;
75:     for (int lane = 0; lane < 8; ++lane) {
76:         factor_lanes[lane] = invSqrt2Pi * expf(-abs_lanes[lane] * abs_lanes[lane] * .5f);
77:     }
78:     w = _mm256_mul_ps(w, _mm256_loadu_ps(factor_lanes));
79: 
80:     const __m256 positive = _mm256_cmp_ps(X, _mm256_setzero_ps(), _CMP_GT_OQ);
81:     const __m256 reflected = _mm256_sub_ps(one, w);
82:     return _mm256_blendv_ps(w, reflected, positive);
83: }
