85: static inline void black_scholes_avx2_block(float Sa[], float Xa[], float Ta[], float ra[], float va[], float result[], int i) {
86:     const __m256 S = _mm256_loadu_ps(Sa + i);
87:     const __m256 X = _mm256_loadu_ps(Xa + i);
88:     const __m256 T = _mm256_loadu_ps(Ta + i);
89:     const __m256 r = _mm256_loadu_ps(ra + i);
