91: 
92:     float ratio_lanes[8];
93:     float log_lanes[8];
94:     _mm256_storeu_ps(ratio_lanes, _mm256_div_ps(S, X));
95:     for (int lane = 0; lane < 8; ++lane)
96:         log_lanes[lane] = logf(ratio_lanes[lane]);
97: 
98:     const __m256 log_ratio = _mm256_loadu_ps(log_lanes);
99:     const __m256 half = _mm256_set1_ps(0.5f);
100:     const __m256 v_squared_half = _mm256_mul_ps(_mm256_mul_ps(v, v), half);
101:     const __m256 rate_vol = _mm256_add_ps(r, v_squared_half);
102:     const __m256 drift = _mm256_mul_ps(rate_vol, T);
103:     const __m256 sqrt_t = _mm256_sqrt_ps(T);
104:     const __m256 numerator = _mm256_add_ps(log_ratio, drift);
105:     const __m256 denominator = _mm256_mul_ps(v, sqrt_t);
106:     const __m256 d1 = _mm256_div_ps(numerator, denominator);
107:     const __m256 d2 = _mm256_sub_ps(d1, _mm256_mul_ps(v, sqrt_t));
108: 
109:     const __m256 cnd1 = CND8(d1);
110:     const __m256 cnd2 = CND8(d2);
111: 
112:     float r_lanes[8];
113:     float t_lanes[8];
114:     float discount_lanes[8];
115:     _mm256_storeu_ps(r_lanes, r);
116:     _mm256_storeu_ps(t_lanes, T);
117:     for (int lane = 0; lane < 8; ++lane)
118:         discount_lanes[lane] = expf(-r_lanes[lane] * t_lanes[lane]);
119: 
120:     const __m256 discount = _mm256_loadu_ps(discount_lanes);
121:     const __m256 first_term = _mm256_mul_ps(S, cnd1);
122:     const __m256 second_term = _mm256_mul_ps(_mm256_mul_ps(X, discount), cnd2);
123:     const __m256 value = _mm256_sub_ps(first_term, second_term);
