158: void binomial_put_serial(float Sa[], float Xa[], float Ta[], float ra[], float va[], float result[], int count) {
159:     float V[BINOMIAL_NUM];
160: 
161:     for (int i = 0; i < count; ++i) {
162:         float S = Sa[i], X = Xa[i];
163:         float T = Ta[i], r = ra[i];
164:         float v = va[i];
165: 
166:         float dt = T / BINOMIAL_NUM;
167:         float u = expf(v * sqrtf(dt));
168:         float d = 1.f / u;
169:         float disc = expf(r * dt);
170:         float Pu = (disc - d) / (u - d);
171: 
172:         for (int j = 0; j < BINOMIAL_NUM; ++j) {
173:             float upow = powf(u, (float)(2 * j - BINOMIAL_NUM));
174:             V[j] = std::max(0.f, X - S * upow);
175:         }
176: 
177:         for (int j = BINOMIAL_NUM - 1; j >= 0; --j)
178:             for (int k = 0; k < j; ++k)
179:                 V[k] = ((1 - Pu) * V[k] + Pu * V[k + 1]) / disc;
180: 
181:         result[i] = V[0];
182:     }
183: }
