33: // Cumulative normal distribution function
34: static inline float CND(float X) {
35:     float L = fabsf(X);
36: 
37:     float k = 1.f / (1.f + 0.2316419f * L);
38:     float k2 = k * k;
39:     float k3 = k2 * k;
40:     float k4 = k2 * k2;
41:     float k5 = k3 * k2;
42: 
43:     const float invSqrt2Pi = 0.39894228040f;
44:     float w = (0.31938153f * k - 0.356563782f * k2 + 1.781477937f * k3 + -1.821255978f * k4 + 1.330274429f * k5);
45:     w *= invSqrt2Pi * expf(-L * L * .5f);
46: 
47:     if (X > 0.f)
48:         w = 1.f - w;
49:     return w;
50: }
