52: void black_scholes_serial(float Sa[], float Xa[], float Ta[], float ra[], float va[], float result[], int count) {
53:     int i = 0;
54: 
55: #if defined(__AVX2__)
56:     const __m256 half = _mm256_set1_ps(0.5f);
57:     const __m256 negative_zero = _mm256_set1_ps(-0.0f);
58: 
59:     for (; count - i >= 8; i += 8) {
60:         __m256 S = _mm256_loadu_ps(Sa + i);
61:         __m256 X = _mm256_loadu_ps(Xa + i);
62:         __m256 T = _mm256_loadu_ps(Ta + i);
63:         __m256 r = _mm256_loadu_ps(ra + i);
64:         __m256 v = _mm256_loadu_ps(va + i);
65: 
66:         // Keep libm logf and the supplied scalar CND unchanged, while batching
67:         // the FP32 divide, square root, and surrounding formula arithmetic.
68:         float ratios[8];
69:         float logarithms[8];
70:         _mm256_storeu_ps(ratios, _mm256_div_ps(S, X));
71:         for (int lane = 0; lane < 8; ++lane)
72:             logarithms[lane] = logf(ratios[lane]);
73: 
74:         __m256 sqrt_T = _mm256_sqrt_ps(T);
75:         __m256 v_sqrt_T = _mm256_mul_ps(v, sqrt_T);
76:         __m256 half_v_squared = _mm256_mul_ps(_mm256_mul_ps(v, v), half);
77:         __m256 drift = _mm256_mul_ps(_mm256_add_ps(r, half_v_squared), T);
78:         __m256 d1 = _mm256_div_ps(_mm256_add_ps(_mm256_loadu_ps(logarithms), drift), v_sqrt_T);
79:         __m256 d2 = _mm256_sub_ps(d1, v_sqrt_T);
80: 
81:         float d1_lanes[8];
82:         float d2_lanes[8];
83:         float exp_arguments[8];
84:         float cnd_d1[8];
85:         float cnd_d2[8];
86:         float exp_values[8];
87:         _mm256_storeu_ps(d1_lanes, d1);
88:         _mm256_storeu_ps(d2_lanes, d2);
89:         __m256 negative_r = _mm256_xor_ps(r, negative_zero);
90:         _mm256_storeu_ps(exp_arguments, _mm256_mul_ps(negative_r, T));
91: 
92:         for (int lane = 0; lane < 8; ++lane) {
93:             cnd_d1[lane] = CND(d1_lanes[lane]);
94:             cnd_d2[lane] = CND(d2_lanes[lane]);
95:             exp_values[lane] = expf(exp_arguments[lane]);
96:         }
97: 
98:         __m256 first_term = _mm256_mul_ps(S, _mm256_loadu_ps(cnd_d1));
99:         __m256 second_term = _mm256_mul_ps(
100:             _mm256_mul_ps(X, _mm256_loadu_ps(exp_values)),
101:             _mm256_loadu_ps(cnd_d2));
102:         _mm256_storeu_ps(result + i, _mm256_sub_ps(first_term, second_term));
103:     }
104: #endif
105: 
106:     for (; i < count; ++i) {
107:         float S = Sa[i], X = Xa[i];
108:         float T = Ta[i], r = ra[i];
109:         float v = va[i];
110: 
111:         float d1 = (logf(S / X) + (r + v * v * .5f) * T) / (v * sqrtf(T));
112:         float d2 = d1 - v * sqrtf(T);
113: 
114:         result[i] = S * CND(d1) - X * expf(-r * T) * CND(d2);
115:     }
116: }
