118: void binomial_put_serial(float Sa[], float Xa[], float Ta[], float ra[], float va[], float result[], int count) {
119:     float V[BINOMIAL_NUM];
120: 
121:     for (int i = 0; i < count; ++i) {
122:         float S = Sa[i], X = Xa[i];
123:         float T = Ta[i], r = ra[i];
124:         float v = va[i];
125: 
126:         float dt = T / BINOMIAL_NUM;
127:         float u = expf(v * sqrtf(dt));
128:         float d = 1.f / u;
129:         float disc = expf(r * dt);
130:         float Pu = (disc - d) / (u - d);
131: 
132:         for (int j = 0; j < BINOMIAL_NUM; ++j) {
133:             float upow = powf(u, (float)(2 * j - BINOMIAL_NUM));
134:             V[j] = std::max(0.f, X - S * upow);
135:         }
136: 
137:         for (int j = BINOMIAL_NUM - 1; j >= 0; --j)
138:             for (int k = 0; k < j; ++k)
139:                 V[k] = ((1 - Pu) * V[k] + Pu * V[k + 1]) / disc;
140: 
141:         result[i] = V[0];
142:     }
143: }
